export const INITECH_SAFEGUARD_IDS = Object.freeze(Object.keys(CONTENT));

export function initechSafeguardContent(definitionId, status) {
  if (typeof definitionId !== 'string' || !Object.hasOwn(CONTENT, definitionId)) {
    throw new Error(`No content for supported CIS IG2 safeguard: ${String(definitionId)}`);
  }
  const expected = INITECH_SCENARIO_PROFILE.partial.includes(definitionId) ? 'in_progress'
    : INITECH_SCENARIO_PROFILE.gaps.includes(definitionId) ? 'needs_attention'
      : INITECH_SCENARIO_PROFILE.unknown.includes(definitionId) ? 'not_assessed' : 'addressed';
  if (status !== expected) {
    throw new Error(`Initech ${definitionId} requires ${expected} content, not ${String(status)}`);
  }
  const row = CONTENT[definitionId];
  const [owner_role, process_owner_role] = OWNERS[definitionId.split('.')[0]];
  return {
    scope: row.scope,
    current_implementation: row.current_implementation,
    technology_process: row.technology_process,
    assessment_notes: row.assessment_notes,
    owner_role,
    process_owner_role,
    evidence_check: row.evidence_check,
    remediation: row.remediation || '',
    assessment_plan: row.assessment_plan || '',
  };
}
